import{_ as d,o as a,c as r,a as e}from"./chunks/framework.Ld7uezS_.js";const c=JSON.parse('{"title":"5. 设施检测","description":"","frontmatter":{},"headers":[],"relativePath":"skill/05-detection.md","filePath":"skill/05-detection.md","lastUpdated":1787283537000}'),o={name:"skill/05-detection.md"};function l(i,t,h,n,s,p){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="_5-设施检测" tabindex="-1">5. 设施检测 <a class="header-anchor" href="#_5-设施检测" aria-label="Permalink to &quot;5. 设施检测&quot;">​</a></h1><h2 id="本章定位" tabindex="-1">本章定位 <a class="header-anchor" href="#本章定位" aria-label="Permalink to &quot;本章定位&quot;">​</a></h2><p>设施检测主要对应检测维修保养方向。检测不是“按一下设备看它动不动”，而是依据标准、方案和设备说明书，对输入、控制、动作、反馈、供电和恢复进行有记录的验证。</p><h2 id="一、检测前准备" tabindex="-1">一、检测前准备 <a class="header-anchor" href="#一、检测前准备" aria-label="Permalink to &quot;一、检测前准备&quot;">​</a></h2><ol><li>明确检测对象、区域、系统范围和检测目的；</li><li>查阅现行标准、检测方案、图纸、设备说明书和历史记录；</li><li>通知消防控制室、相关岗位和可能受影响人员；</li><li>评估误启动消防泵、风机、卷帘、广播或气体灭火的风险；</li><li>准备警示、隔离、监护、复位和恢复措施；</li><li>核对仪器量程、精度、校准/检定状态、电池和接线。</li></ol><h2 id="二、先分清-检查、测量、试验、检测和判定" tabindex="-1">二、先分清“检查、测量、试验、检测和判定” <a class="header-anchor" href="#二、先分清-检查、测量、试验、检测和判定" aria-label="Permalink to &quot;二、先分清“检查、测量、试验、检测和判定”&quot;">​</a></h2><table tabindex="0"><thead><tr><th>词语</th><th>零基础理解</th><th>例子</th><th>能证明什么</th></tr></thead><tbody><tr><td>检查</td><td>观察、核对状态或资料</td><td>看阀门位置、铭牌、外观</td><td>是否存在明显异常或条件不满足</td></tr><tr><td>测量</td><td>用仪器取得数值</td><td>测电压、压力、照度或电阻</td><td>某测点在某条件下的客观读数</td></tr><tr><td>试验</td><td>按规定触发或模拟动作</td><td>末端试水、触发手报、测试广播</td><td>输入后系统是否出现预期响应</td></tr><tr><td>检测</td><td>按依据组织检查、测量、试验并形成结论</td><td>对一套系统实施检测</td><td>对规定项目和范围的综合结果</td></tr><tr><td>判定</td><td>将实测结果与依据比较</td><td>合格、不符合或待复核</td><td>当前证据支持的结论，不是凭感觉下结论</td></tr></tbody></table><p>一个电压读数只能证明测点当时的电压状态，不能单独证明控制器逻辑、现场动作和反馈都正常；一次末端试水有水，也不能自动证明整个建筑所有分区的供水能力都合格。</p><h2 id="二、检测的五个结果" tabindex="-1">二、检测的五个结果 <a class="header-anchor" href="#二、检测的五个结果" aria-label="Permalink to &quot;二、检测的五个结果&quot;">​</a></h2><p>检测时先问“我要证明什么”，再选择触发方式和仪器。一个完整项目至少要有：</p><ol><li><strong>对象</strong>：设备名称、编号、区域和系统范围；</li><li><strong>方法</strong>：触发方式、仪器、接线和适用方案；</li><li><strong>预期</strong>：依据文件规定的显示、动作、反馈和恢复结果；</li><li><strong>实测</strong>：实际显示、动作、反馈、测量值和异常；</li><li><strong>结论</strong>：符合、不符合或暂不能判定，以及后续措施。</li></ol><p>每个项目至少记录：</p><ul><li><strong>输入/触发</strong>：什么探测器、按钮、试水或信号被触发；</li><li><strong>显示</strong>：控制器显示了什么地址、类别和时间；</li><li><strong>动作</strong>：风机、泵、广播、卷帘或其他设备是否动作；</li><li><strong>反馈</strong>：控制器是否收到设备到位、运行或故障反馈；</li><li><strong>恢复</strong>：复位后是否回到规定状态，有无新增故障。</li></ul><p>只记录“设备动作了”是不完整的检测结论。</p><h2 id="三、先学会仪器上的四个基本词" tabindex="-1">三、先学会仪器上的四个基本词 <a class="header-anchor" href="#三、先学会仪器上的四个基本词" aria-label="Permalink to &quot;三、先学会仪器上的四个基本词&quot;">​</a></h2><p>零基础拿到仪器时，先不要急着接线。先理解四个词：</p><ul><li><strong>功能/档位</strong>：仪器准备测什么，例如电压、通断、压力或风速；档位选错，可能得到错误结果，甚至损坏仪器或设备；</li><li><strong>量程</strong>：仪器允许测量的范围。被测值可能多大不确定时，应按说明书和安全规程从合适的较大范围开始，不能凭感觉跨档；</li><li><strong>分辨力</strong>：仪器能区分多细的变化。显示更多位数不等于结果一定更准确；</li><li><strong>校准/检定状态</strong>：说明仪器是否在规定有效状态内。仪器能开机不等于读数就能作为检测依据。</li></ul><p>拿仪器前先回答：<strong>我要证明什么、测哪里、被测对象是否带电/带压、用什么档位、结果和哪份依据比较、测完如何安全拆除并恢复</strong>。任何一个问题答不上来，都不应直接测量。</p><h2 id="四、仪器与检测记录" tabindex="-1">四、仪器与检测记录 <a class="header-anchor" href="#四、仪器与检测记录" aria-label="Permalink to &quot;四、仪器与检测记录&quot;">​</a></h2><p>仪器不是“拿来测一下”就结束，至少要在检测前后确认：</p><table tabindex="0"><thead><tr><th>检查项</th><th>为什么重要</th><th>记录方式</th></tr></thead><tbody><tr><td>仪器名称和编号</td><td>证明使用了什么工具</td><td>写明型号/编号，避免与现场设备混淆</td></tr><tr><td>量程和分辨力</td><td>防止超量程或读数过粗</td><td>记录量程、单位和显示位数</td></tr><tr><td>校准/检定状态</td><td>判断读数能否作为依据</td><td>记录有效期或状态标识</td></tr><tr><td>接线和探头</td><td>防止接错端子或测错对象</td><td>按方案和仪器说明书核对</td></tr><tr><td>使用前后状态</td><td>防止电池、探头或仪器故障影响结果</td><td>记录异常、复测或更换仪器情况</td></tr></tbody></table><blockquote><p>不同检测任务所需仪器、精度和接线不同。本页不把某一种仪器或统一精度写成所有项目的固定要求；应以现行检测依据、方案和仪器说明书为准。</p></blockquote><h2 id="四、检测仪器选择与使用卡" tabindex="-1">四、检测仪器选择与使用卡 <a class="header-anchor" href="#四、检测仪器选择与使用卡" aria-label="Permalink to &quot;四、检测仪器选择与使用卡&quot;">​</a></h2><p>仪器选择先看“要验证的对象和证据”，再看量程、分辨力、环境适应性、接头/探头匹配和校准/检定状态。没有适用仪器、方法或安全条件时，应停止测量并报告，不能用相近工具替代并套用结论。</p><table tabindex="0"><thead><tr><th>工具</th><th>选择依据</th><th>使用前检查</th><th>基本操作</th><th>常见误用</th><th>原始记录与异常复测</th></tr></thead><tbody><tr><td>万用表</td><td>被测量是电压、通断、电阻或其他电气状态；按回路类别、量程和安全等级选择</td><td>表体、表笔绝缘和插孔无损；电池、档位、量程、保险和校准/检定状态正常</td><td>先识别被测对象和带电状态；先选功能/量程再接表笔；按方案接线、读数、断开并恢复</td><td>电流档并联测电压；未确认回路就测量；超量程；以通断蜂鸣代替功能检测；带电拆接表笔</td><td>记录测点、状态、档位、量程、单位、读数、时间、仪器编号；读数异常先保留原始值，核对接线/量程并用适用方法复测</td></tr><tr><td>绝缘测试工具</td><td>需要验证线路、设备或电气部件绝缘性能，且依据明确要求该方法</td><td>测试电压档位、端子、导线绝缘、放电功能和校准/检定状态；确认被测设备可隔离</td><td>按方案断电、验电、隔离并确认不影响其他功能；按仪器说明书测试，结束后放电、复核并恢复</td><td>对带电或未隔离回路直接测试；把绝缘读数当作整套设备功能合格；测试后不放电</td><td>记录对象、隔离范围、测试档位/方法、读数和单位、放电及恢复结果；异常须由授权人员复核，不能用重复测试覆盖首次结果</td></tr><tr><td>压力测试工具</td><td>需要验证水系统压力，测点、系统形式和测试条件已由方案确定</td><td>量程、接口、密封、软管、零点、显示/指针和校准/检定状态正常</td><td>核对测点和阀门，按方案连接并缓慢取压；稳定后读数，记录条件，再安全卸压/拆除</td><td>把现场表盘读数当作仪器校验结果；测点不明；快速开关阀门；把静态压力外推为流量或全系统性能</td><td>记录测点、系统状态、取压条件、仪器编号、读数、单位和时间；异常先检查泄漏、接口和测点，再按同一条件或指定方法复测</td></tr><tr><td>风速/风量仪器</td><td>需要验证送风、排烟气流，按方案确定测点、截面、布点和计算方法</td><td>探头、方向标识、电池、量程、校准/检定状态和环境条件正常</td><td>按测量方法定位探头，保持方向和位置稳定；按方案读取多个点或计算风量，记录环境和截面</td><td>用单点读数代表整截面；探头方向错误；忽略门窗、风阀、风机状态；混用风速和风量概念</td><td>记录测点/截面、风机风阀状态、环境、布点方法、各点原始值、计算方法、单位和依据；结果异常时检查状态并按方案复测</td></tr><tr><td>声级计</td><td>需要验证警报、广播等声响效果，位置、背景条件和评价方法已有依据</td><td>量程、频率/计权设置、响应方式、电池、传声器和校准状态正常</td><td>按方案在指定位置测量，记录背景噪声和设备状态，必要时分区/分模式取值</td><td>把背景噪声当设备读数；改变计权/响应设置；靠近声源随意测量；用一次读数代表全区域</td><td>记录测点、背景、设备分区/模式、设置、读数、单位、仪器编号和依据；背景突变或读数不稳定时说明原因并按方案复测</td></tr><tr><td>烟温模拟工具</td><td>需要向感烟/感温探测器提供与类型匹配的测试输入</td><td>工具适配型号、输出状态、电量、外观和校准/功能状态正常；确认不会造成非授权联动</td><td>按方案和产品说明书选择模拟方式，逐点触发并观察控制器、现场警报、联动/反馈，再按规定复位</td><td>用真实烟火、热源或不适配介质替代；跨类型使用；连续触发真实联动；只看探测器指示灯</td><td>记录探测器类型/地址、模拟方式、控制器显示、现场动作、反馈、复位和时间；异常保留首次结果，核对工具匹配性后再授权复测</td></tr><tr><td>反馈/通断检查工具</td><td>需要核对触点、模块输入或反馈链的状态，且方案允许该检查</td><td>接线、极性、量程、端子、表笔和校准/检定状态正常；确认不改变回路状态</td><td>按图纸和方案定位反馈点，记录原状态后测量/观察，结束后断开工具并核对恢复</td><td>用短接、拔线或外加信号伪造“正常反馈”；把触点通断当作现场设备动作；不记录原状态</td><td>记录反馈来源、点位、原状态、方法、读数/状态、控制器显示和恢复；异常分开记录现场动作与反馈缺失，按方案复测</td></tr></tbody></table><blockquote><p>所有仪器的精度、允许误差、测量位置、抽检比例、动作时间和合格阈值，必须回到适用标准、检测方案、设计文件、设备说明书和鉴定站要求；本页不提供脱离依据的统一数值。</p></blockquote><h2 id="五、按系统组织检测步骤与判定边界" tabindex="-1">五、按系统组织检测步骤与判定边界 <a class="header-anchor" href="#五、按系统组织检测步骤与判定边界" aria-label="Permalink to &quot;五、按系统组织检测步骤与判定边界&quot;">​</a></h2><h3 id="_5-1-火灾自动报警与联动" tabindex="-1">5.1 火灾自动报警与联动 <a class="header-anchor" href="#_5-1-火灾自动报警与联动" aria-label="Permalink to &quot;5.1 火灾自动报警与联动&quot;">​</a></h3><p><strong>检测前</strong>：明确地址/区域、检测目的、预期输入和联动对象；查图纸、现行依据、方案、说明书、历史记录及屏蔽/隔离清单；通知控制室和受影响岗位，确认警报、泵、风机、卷帘、广播、电梯或气体灭火是否会动作；准备匹配的烟温模拟工具、反馈检查工具或电气仪器，落实授权、监护和恢复责任。</p><p><strong>检测中</strong>：按设备类型和方案触发探测器、手报或模拟输入；依次记录触发时间、控制器地址/类别/时间显示、声光或广播、联动输出、现场设备动作、运行/到位/故障反馈；需要测量时同时记录仪器、档位/设置、测点、单位和环境。严禁用短接、拔线、随意加烟加热或重复真实联动替代方法。</p><p><strong>检测后</strong>：按方案复位输入和控制器，恢复自动/联动/监视、主备电和屏蔽/隔离状态；核对控制室无新增故障，现场执行机构已回到规定状态；形成“对象—方法—原始结果—判定依据—异常—复测—恢复”记录。</p><p><strong>判定边界</strong>：输入、显示、输出、现场动作和反馈必须分别取证；“控制器有输出”“现场设备会动”均不能单独判定合格。异常时先保留原始记录并评估保护影响，维修或调整后按同一依据复测，复测不能覆盖首次异常。</p><h3 id="_5-2-消防给水与自动灭火系统" tabindex="-1">5.2 消防给水与自动灭火系统 <a class="header-anchor" href="#_5-2-消防给水与自动灭火系统" aria-label="Permalink to &quot;5.2 消防给水与自动灭火系统&quot;">​</a></h3><p><strong>检测前</strong>：确认系统形式、分区、测试点、授权、排水和防淹条件；核对水源/水位、阀门状态、泵组供电、控制方式、压力测点和控制室监视；选择匹配的压力/流量或反馈工具，确认量程、接口、校准/检定和记录字段；放水或启泵前通知相关岗位并设置监护。</p><p><strong>检测中</strong>：按方案进行泵组、主备切换、报警阀组、末端试水、水流指示器、压力开关或消火栓等测试；记录触发条件、压力/流量及单位、仪器信息、现场水力动作、警铃/泵动作、控制室显示和反馈；不擅自关阀、改设定、扩大放水或人为制造故障。</p><p><strong>检测后</strong>：按方案停止放水/试验，确认排水完成、无渗漏、阀门和泵组控制方式恢复，自动/联动/监视和控制室信息正常；记录测试点及条件、原始值、依据、异常、临时措施、复测结果和复核人。</p><p><strong>判定边界</strong>：末端有水不等于全系统供水合格，电机运转不等于泵组功能合格，压力表有读数不等于仪表准确；压力、流量、持续时间、动作时间和允许误差必须引用适用依据，不能凭记忆填值。</p><h3 id="_5-3-其他消防设施" tabindex="-1">5.3 其他消防设施 <a class="header-anchor" href="#_5-3-其他消防设施" aria-label="Permalink to &quot;5.3 其他消防设施&quot;">​</a></h3><p><strong>检测前</strong>：按对象确认区域、动作范围和人员安全；防烟排烟要核对风机/风阀编号、测风截面和风速风量方法，卷帘要清场，电梯要联系维保单位，照明/广播/电话要确认主备电和分区，消火栓要确认排水；落实误动作、机械运动和电气作业防护。</p><p><strong>检测中</strong>：按方案分别验证风机运行、风阀到位、风速/风量、卷帘/防火门/防火阀动作、应急转换、照明/广播/电话效果、电梯迫降接口和消火栓组件；记录控制命令、现场动作、反馈、仪器设置及原始测量值，不把风机转动、单灯点亮、单个扬声器有声或门体移动作为完整结论。</p><p><strong>检测后</strong>：恢复风机/阀门、门卷帘位置、照明主电、广播电话常态、电梯正常服务和消火栓阀门/排水状态；核对控制室自动/联动/监视和故障信息，清点临时隔离，记录未解决问题及报告对象。</p><p><strong>判定边界</strong>：必须以对应系统的设计文件、现行标准、设备说明书、检测方案和专业协同结论判定；照度、转换时间、持续时间、风量风压、声级和动作时间不得脱离依据写死。机械动作、反馈、性能数据和恢复状态缺一项时，只能判为待复核或不符合相应要求，不能笼统写“正常”。</p><h2 id="六、按系统理解检测" tabindex="-1">六、按系统理解检测 <a class="header-anchor" href="#六、按系统理解检测" aria-label="Permalink to &quot;六、按系统理解检测&quot;">​</a></h2><h3 id="火灾自动报警系统" tabindex="-1">火灾自动报警系统 <a class="header-anchor" href="#火灾自动报警系统" aria-label="Permalink to &quot;火灾自动报警系统&quot;">​</a></h3><p>检查探测器、手动报警按钮、声光警报器、输入/输出模块、控制器显示、打印/记录、主备电和联动反馈。测试时要防止触发真实联动造成设备误动作。</p><h3 id="消防联动控制" tabindex="-1">消防联动控制 <a class="header-anchor" href="#消防联动控制" aria-label="Permalink to &quot;消防联动控制&quot;">​</a></h3><p>按方案验证报警信号与泵、风机、风阀、广播、电话、卷帘和电梯迫降等对象之间的逻辑关系。每次测试都要明确触发条件、预期动作和反馈位置。</p><h3 id="水系统" tabindex="-1">水系统 <a class="header-anchor" href="#水系统" aria-label="Permalink to &quot;水系统&quot;">​</a></h3><p>根据方案检查泵组启停、主备切换、末端试水、报警阀组、水流指示器、压力开关和控制器信号。压力、流量、持续时间等阈值不能凭记忆填写，必须引用检测依据。</p><h3 id="防烟排烟系统" tabindex="-1">防烟排烟系统 <a class="header-anchor" href="#防烟排烟系统" aria-label="Permalink to &quot;防烟排烟系统&quot;">​</a></h3><p>检查风机、风阀、排烟口/送风口动作、控制器显示、反馈和恢复。现场人员必须远离运动部件并落实误启动防护。</p><h2 id="五、异常判定与复测" tabindex="-1">五、异常判定与复测 <a class="header-anchor" href="#五、异常判定与复测" aria-label="Permalink to &quot;五、异常判定与复测&quot;">​</a></h2><p>出现以下情况时，不能直接写“合格”：</p><ul><li>触发端有输入，但控制器没有对应显示；</li><li>控制器显示有输出，但现场设备没有动作；</li><li>现场设备动作，但控制器没有运行、到位或故障反馈；</li><li>结果与设计逻辑、设备说明书或检测方案不一致；</li><li>测量值缺少单位、仪器信息或适用判定依据；</li><li>检测结束后设备仍处于手动、屏蔽、隔离、停用或故障状态。</li></ul><p>处理顺序是：<strong>保留原始现象 → 判断保护影响 → 报告并落实临时防护 → 按授权维修或复测 → 重新记录结果 → 确认恢复状态</strong>。复测不能覆盖原始异常记录。</p><h2 id="六、检测记录示例" tabindex="-1">六、检测记录示例 <a class="header-anchor" href="#六、检测记录示例" aria-label="Permalink to &quot;六、检测记录示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>应记录内容</th></tr></thead><tbody><tr><td>对象</td><td>设备名称、编号、位置</td></tr><tr><td>方法</td><td>触发方式、仪器、接线和方案</td></tr><tr><td>结果</td><td>显示、动作、反馈、测量值</td></tr><tr><td>判定依据</td><td>标准/版本、设备说明书、检测方案</td></tr><tr><td>异常</td><td>未动作、无反馈、误报警、参数异常</td></tr><tr><td>后续</td><td>临时措施、维修建议、报告和复测</td></tr></tbody></table><h2 id="六、自测" tabindex="-1">六、自测 <a class="header-anchor" href="#六、自测" aria-label="Permalink to &quot;六、自测&quot;">​</a></h2><ol><li>检测和日常保养有什么区别？</li><li>为什么“有动作”不能直接等于“合格”？</li><li>检测前为什么必须通知相关岗位？</li><li>哪些数值必须查标准和检测方案？</li></ol><blockquote><p>参考：<a href="https://xfhyjd.119.gov.cn/" target="_blank" rel="noreferrer">《消防设施操作员国家职业技能标准（2019年版）》</a>；检测阈值、允许误差和动作时间必须以现行国家标准、地方鉴定站实施细则、设备说明书和检测方案为准。现场检测必须由经过培训和授权的人员实施。</p></blockquote>',60)])])}const g=d(o,[["render",l]]);export{c as __pageData,g as default};
